import{_ as o,o as i,c as l,a2 as e,j as a,a as r}from"./chunks/framework.A5mep7Fe.js";const _=JSON.parse('{"title":"🎯 05 · 对齐技术（Alignment）：SFT · RLHF · DPO · GRPO","description":"","frontmatter":{},"headers":[],"relativePath":"01-算法岗-AIGC与LLM/05-对齐技术.md","filePath":"01-算法岗-AIGC与LLM/05-对齐技术.md","lastUpdated":1786806808000}'),n={name:"01-算法岗-AIGC与LLM/05-对齐技术.md"};function p(s,t,d,h,c,g){return i(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="🎯-05-·-对齐技术-alignment-sft-·-rlhf-·-dpo-·-grpo" tabindex="-1">🎯 05 · 对齐技术（Alignment）：SFT · RLHF · DPO · GRPO <a class="header-anchor" href="#🎯-05-·-对齐技术-alignment-sft-·-rlhf-·-dpo-·-grpo" aria-label="Permalink to &quot;🎯 05 · 对齐技术（Alignment）：SFT · RLHF · DPO · GRPO&quot;">​</a></h1><blockquote><p>对齐 = 让模型「有用、诚实、无害」。这是 2023 后大模型差异化的核心，面试高频且易深挖。</p></blockquote><hr><h2 id="一、对齐的整体流程" tabindex="-1">一、对齐的整体流程 <a class="header-anchor" href="#一、对齐的整体流程" aria-label="Permalink to &quot;一、对齐的整体流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>基座模型 → SFT（监督微调，学会格式/能力）→ 奖励建模（RM）→ RL 优化（RLHF/DPO）</span></span></code></pre></div><ul><li><strong>SFT</strong>：用高质量「指令-回答」教模型会做事。</li><li><strong>RM（Reward Model）</strong>：学「人类偏好」的打分函数。</li><li><strong>RL</strong>：用 RM 做信号，强化模型生成「高分回答」。</li></ul><hr><h2 id="二、rlhf-三阶段-经典" tabindex="-1">二、RLHF 三阶段（经典） <a class="header-anchor" href="#二、rlhf-三阶段-经典" aria-label="Permalink to &quot;二、RLHF 三阶段（经典）&quot;">​</a></h2><h3 id="阶段1-sft-supervised-fine-tuning" tabindex="-1">阶段1：SFT（Supervised Fine-Tuning） <a class="header-anchor" href="#阶段1-sft-supervised-fine-tuning" aria-label="Permalink to &quot;阶段1：SFT（Supervised Fine-Tuning）&quot;">​</a></h3><p>用标注数据微调，得到初始策略 $\\pi_{SFT}$。</p><h3 id="阶段2-训练奖励模型-rm" tabindex="-1">阶段2：训练奖励模型 RM <a class="header-anchor" href="#阶段2-训练奖励模型-rm" aria-label="Permalink to &quot;阶段2：训练奖励模型 RM&quot;">​</a></h3><p>收集「同一 prompt 的多个回答 + 人类排序」，训一个打分模型 $r_\\theta(x,y)$。损失用 Bradley-Terry 偏好模型：</p>',12),a("p",null,[r("$$\\mathcal{L}"),a("em",{"(x,y_w,y_l)":""},"{RM} = -\\mathbb{E}"),r("\\left[\\log \\sigma(r_\\theta(x,y_w) - r_\\theta(x,y_l))\\right]$$")],-1),e('<p>$y_w$ 胜出回答，$y_l$ 落败回答。</p><h3 id="阶段3-ppo-强化学习" tabindex="-1">阶段3：PPO 强化学习 <a class="header-anchor" href="#阶段3-ppo-强化学习" aria-label="Permalink to &quot;阶段3：PPO 强化学习&quot;">​</a></h3><p>用 RM 作为奖励，PPO 优化策略，同时加 <strong>KL 惩罚</strong>防止偏离 SFT 太远：</p><p>$$\\max_\\pi \\mathbb{E}<em>{x\\sim D, y\\sim\\pi}\\left[r</em>\\theta(x,y) - \\beta, \\text{KL}(\\pi(\\cdot|x),|,\\pi_{ref}(\\cdot|x))\\right]$$</p><p><strong>为什么加 KL？</strong> 防止模型为了刷 RM 高分而「欺骗奖励」（reward hacking），保持语言自然。</p><hr><h2 id="三、dpo-direct-preference-optimization-⭐" tabindex="-1">三、DPO（Direct Preference Optimization）⭐ <a class="header-anchor" href="#三、dpo-direct-preference-optimization-⭐" aria-label="Permalink to &quot;三、DPO（Direct Preference Optimization）⭐&quot;">​</a></h2><p><strong>思想</strong>：不需要显式 RM 和 RL，直接用一个分类损失在偏好数据上优化策略。</p><p>$$\\mathcal{L}<em>{DPO} = -\\mathbb{E}\\left[\\log \\sigma\\left(\\beta \\log\\frac{\\pi</em>\\theta(y_w|x)}{\\pi_{ref}(y_w|x)} - \\beta \\log\\frac{\\pi_\\theta(y_l|x)}{\\pi_{ref}(y_l|x)}\\right)\\right]$$</p><p><strong>DPO 的优势</strong>：</p><ul><li>省去训 RM + 跑 RL 的复杂流程，训练更稳定</li><li>只需偏好对，实现简单（一个交叉熵式损失）</li><li>工业界大量采用</li></ul><p><strong>DPO vs PPO</strong>：</p><table tabindex="0"><thead><tr><th></th><th>PPO/RLHF</th><th>DPO</th></tr></thead><tbody><tr><td>是否需要 RM</td><td>是</td><td>否（隐式）</td></tr><tr><td>是否需要 RL 循环</td><td>是</td><td>否</td></tr><tr><td>稳定性</td><td>较难</td><td>较易</td></tr><tr><td>效果上限</td><td>通常更高（可在线迭代）</td><td>接近，且更省</td></tr></tbody></table><hr><h2 id="四、grpo-group-relative-policy-optimization" tabindex="-1">四、GRPO（Group Relative Policy Optimization） <a class="header-anchor" href="#四、grpo-group-relative-policy-optimization" aria-label="Permalink to &quot;四、GRPO（Group Relative Policy Optimization）&quot;">​</a></h2><p><strong>用于推理模型（如 DeepSeek-R1）</strong>。省去独立 critic/value 网络：对同一 prompt 采样一组回答，用<strong>组内相对得分</strong>做基线。</p><ul><li>优势：省显存（无 value 网络）、适合数学/代码等可验证奖励</li><li>常与「可验证奖励 RL（RLVR）」结合：用单元测试/答案对错当奖励，而非训练 RM</li></ul><hr><h2 id="五、对齐的核心难题" tabindex="-1">五、对齐的核心难题 <a class="header-anchor" href="#五、对齐的核心难题" aria-label="Permalink to &quot;五、对齐的核心难题&quot;">​</a></h2><ol><li><strong>Reward Hacking</strong>：模型钻 RM 空子（如冗长、拍马）。需 RM 迭代 + 在线人类反馈。</li><li><strong>分布偏移</strong>：RM 只在有限数据上训，策略偏移后 RM 不再准。</li><li><strong>偏好数据质量</strong>：标注一致性差会严重拖累。</li><li><strong>过度对齐（Over-alignment）</strong>：过度安全/谄媚，反而能力下降。</li></ol><hr><h2 id="六、高频追问" tabindex="-1">六、高频追问 <a class="header-anchor" href="#六、高频追问" aria-label="Permalink to &quot;六、高频追问&quot;">​</a></h2><p><strong>Q1：为什么需要 KL 惩罚？</strong></p><blockquote><p>防止策略为刷奖励而生成不自然/偏离分布的文本，保持语言流畅与多样性。</p></blockquote><p><strong>Q2：DPO 为什么能不用 RM？</strong></p><blockquote><p>DPR 把「RM 打分 + KL 约束」的最优解写成闭式，直接转化为策略间的偏好比损失，等效于隐式对齐。</p></blockquote><p><strong>Q3：PPO 和 DPO 怎么选？</strong></p><blockquote><p>追求极致且能跑 RL 管线 → PPO（尤其在线迭代）；追求简单稳定 → DPO。R1 类推理模型常用 GRPO/RLVR。</p></blockquote><p><strong>Q4：什么是 RLHF 的 reward hacking？怎么缓解？</strong></p><blockquote><p>模型利用 RM 漏洞得高分但质量差。缓解：RM 持续用新数据更新、加 KL、多维度奖励、人工抽检。</p></blockquote><hr><p>➡️ 下一步：<a href="./06-解码与推理优化">06-解码与推理优化</a></p>',32)])])}const m=o(n,[["render",p]]);export{_ as __pageData,m as default};
